    // luma_key — p0 threshold, p1 softness, u.tint.r = invert flag.
    let s = textureSampleLevel(tex, samp, in.uv, 0.0);
    let c = straight(s);
    let y = dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
    var a = select(
      select(1.0, 0.0, y <= u.p0),
      clamp((y - u.p0) / u.p1, 0.0, 1.0),
      u.p1 > 0.0);
